			before, err := selected.ListFlowInstanceRouteRecords(ctx, route)
			if err != nil || len(before) == 0 {
				t.Fatalf("load prior exact route set: routes=%#v err=%v", before, err)
			}
			if !runtime.bus.HasFlowInstanceRoute(route) {
				t.Fatal("created process route is not active before terminalization")
			}
			failReplacement()
			err = runtime.manager.DeactivateFlowInstanceModel(ctx, runtimepipeline.FlowInstanceDeactivationRequest{ContractBundle: source, Instance: runtimeflowidentity.Stored(source, notifyallchildren.ChildFlowID, descriptor.FlowInstance, descriptor.InstanceID, descriptor.EntityID, ""), FinalState: "active"})
