func TestHandleEmitTool_TemplateAgentEmissionReachesSameInstanceNodeAndTerminalizesEntity(t *testing.T) {
	for _, nameCase := range []struct {
		name    string
		agentID string
		opts    notifyallchildren.Options
	}{{name: "omitted_id", agentID: "account-worker"}, {name: "literal_override", agentID: "account-handler", opts: notifyallchildren.Options{ExplicitAgentName: true}}} {
		for _, tc := range []struct {
			name  string
			setup func(*testing.T) (notifyAllChildrenStore, *sql.DB)
		}{{name: "postgres", setup: func(t *testing.T) (notifyAllChildrenStore, *sql.DB) {
			_, db, cleanup := testutil.StartPostgres(t)
			t.Cleanup(cleanup)
			return storetest.AdmitPostgresRuntimeStore(t, db), db
		}}, {name: "sqlite", setup: func(t *testing.T) (notifyAllChildrenStore, *sql.DB) {
			backend := storetest.StartSQLiteRuntimeStore(t)
			return backend, storetest.DatabaseForTest(backend)
		}}} {
			for _, cardinality := range []int{1, 2, 3} {
				t.Run(fmt.Sprintf("%s/%s/n=%d", nameCase.name, tc.name, cardinality), func(t *testing.T) {
					ctx := testAuthorActivityContext(context.Background())
					backend, db := tc.setup(t)
					runID := uuid.NewString()
					ctx = runtimecorrelation.WithRunID(ctx, runID)
					source := notifyallchildren.LoadSource(t, nameCase.opts)
					gate := newNotifyAllChildrenAgentGate()
					runtime := newNotifyAllChildrenRuntime(t, backend, db, source, time.Now, notifyAllChildrenRuntimeOptions{realMockAgents: true, agentGate: gate, diagnosticOverlap: cardinality == 3})
					t.Cleanup(func() {
						if t.Failed() {
							diagnostics, err := json.Marshal(runtime.diagnostics.snapshot())
							t.Logf("notify-all-children runtime diagnostics: %s (encoding error: %v)", diagnostics, err)
						}
					})
					runCtx := runtimeeffects.WithExecutionMode(managedConformanceExecutionContextForBundle(t, ctx, "notify-all-children-fixed-slug", runtime.sourceArtifactFact), runtime.posture.RootMode())
					if err := runtime.manager.Run(runCtx); err != nil {
						t.Fatalf("run manager: %v", err)
					}
					publishNotifyAllChildrenRunCreatingEvent(t, ctx, runtime, source, runID, "portfolio.opened", map[string]any{"portfolio_id": "portfolio-main"})
					accountIDs := make([]string, 0, cardinality)
					for i := 0; i < cardinality; i++ {
						accountIDs = append(accountIDs, fmt.Sprintf("acct-%d", i+1))
					}
					publishNotifyAllChildrenEvent(t, ctx, runtime, source, runID, "portfolio.accounts.register.requested", map[string]any{"portfolio_id": "portfolio-main", "account_ids": accountIDs})
					descriptors := notifyAllChildrenAccountDescriptors(t, ctx, backend)
					if len(descriptors) != cardinality {
						t.Fatalf("active account descriptors = %#v, want %d", descriptors, cardinality)
					}
					assertNotifyAllChildrenConcreteAgentSet(t, ctx, backend, descriptors, nameCase.agentID)
					blocked := descriptors[accountIDs[len(accountIDs)-1]].FlowInstance
					gate.block(blocked)
					publishNotifyAllChildrenEventAsync(t, ctx, runtime, source, runID, "portfolio.notify.requested", map[string]any{"portfolio_id": "portfolio-main", "command": "notify-every-account"})
					gate.waitStarted(t, blocked)
					for _, accountID := range accountIDs[:len(accountIDs)-1] {
						waitNotifyAllChildrenEntityState(t, ctx, backend, db, descriptors[accountID].FlowInstance, "completed")
					}
					if got := loadNotifyAllChildrenEntityState(t, ctx, backend, db, blocked); got != "active" {
						t.Fatalf("blocked sibling status = %q, want active while another instance is terminal", got)
					}
					if _, err := runtime.manager.ResolveAgentConfig(runID, nameCase.agentID, blocked); err != nil {
						t.Fatalf("blocked sibling agent disappeared after another instance terminated: %v", err)
					}
					waitNotifyAllChildrenAgentDeliveryStatus(t, ctx, backend, runID, nameCase.agentID, blocked, "in_progress")
					gate.release(blocked)
					waitNotifyAllChildrenRuntime(t, runtime, runID)
					for _, accountID := range accountIDs {
						instancePath := descriptors[accountID].FlowInstance
						waitNotifyAllChildrenEntityState(t, ctx, backend, db, instancePath, "completed")
						waitNotifyAllChildrenAgentDeliveryStatus(t, ctx, backend, runID, nameCase.agentID, instancePath, "delivered")
						assertNotifyAllChildrenAgentEmissionSettledToSameInstanceNode(t, ctx, db, tc.name, runID, nameCase.agentID, instancePath)
						waitNotifyAllChildrenAgentRetainedIdle(t, ctx, backend, runtime.manager, runID, nameCase.agentID, instancePath)
					}
					assertNotifyAllChildrenCompletedTurns(t, ctx, backend, runID, nameCase.agentID, cardinality)
					assertNotifyAllChildrenConcreteAgentSet(t, ctx, backend, descriptors, nameCase.agentID)
					if retained, err := backend.LoadAgents(ctx); err != nil {
						t.Fatalf("LoadAgents after ordinary final-stage entry: %v", err)
					} else if len(retained) != cardinality {
						t.Fatalf("retained agents after ordinary final-stage entry = %#v, want exactly %d", retained, cardinality)
					}
					if cardinality == 3 {
						removed := descriptors[accountIDs[0]]
						if err := runtime.manager.DeactivateFlowInstanceModel(ctx, runtimepipeline.FlowInstanceDeactivationRequest{ContractBundle: source, Instance: runtimeflowidentity.Stored(source, notifyallchildren.ChildFlowID, removed.FlowInstance, removed.InstanceID, removed.EntityID, ""), FinalState: "completed"}); err != nil {
							t.Fatalf("explicit completed-child deactivation: %v", err)
						}
						waitNotifyAllChildrenRuntime(t, runtime, runID)
						if _, err := runtime.manager.ResolveAgentConfig(runID, nameCase.agentID, removed.FlowInstance); !errors.Is(err, runtimemanager.ErrAgentNotFound) {
							t.Fatalf("explicitly deactivated child remains process-visible: %v", err)
						}
						remaining := make(map[string]runtimebus.ActiveFlowInstanceDescriptor, cardinality-1)
						for _, accountID := range accountIDs[1:] {
							remaining[accountID] = descriptors[accountID]
							waitNotifyAllChildrenAgentRetainedIdle(t, ctx, backend, runtime.manager, runID, nameCase.agentID, descriptors[accountID].FlowInstance)
						}
						assertNotifyAllChildrenConcreteAgentSet(t, ctx, backend, remaining, nameCase.agentID)
					}
				})
			}
		}
	}
}

