func runNumericFanOutReporterShape(t *testing.T, transactionOptions storetest.TransactionProbeOptions, issuanceBudget time.Duration, parallelBackends bool) {
	for _, tc := range []struct {
		name  string
		setup func(*testing.T) (notifyAllChildrenStore, *sql.DB)
	}{{name: "postgres", setup: func(t *testing.T) (notifyAllChildrenStore, *sql.DB) {
		_, db, cleanup := testutil.StartPostgres(t)
		t.Cleanup(cleanup)
		return storetest.AdmitPostgresRuntimeStore(t, db), db
	}}, {name: "sqlite", setup: func(t *testing.T) (notifyAllChildrenStore, *sql.DB) {
		selected := storetest.StartSQLiteRuntimeStore(t)
		return selected, storetest.DatabaseForTest(selected)
	}}} {
		t.Run(tc.name, func(t *testing.T) {
			if parallelBackends {
				t.Parallel()
			}
			selected, db := tc.setup(t)
			source := notifyallchildren.LoadSource(t, notifyallchildren.Options{NumericRegistrationRows: true, NumericReporterSink: true, RegistrationUUIDField: true})
			runtime := newNotifyAllChildrenRuntime(t, selected, db, source, time.Now)
			validRunID := uuid.NewString()
			validCtx := runtimecorrelation.WithRunID(testAuthorActivityContext(context.Background()), validRunID)
			if err := runtime.manager.Run(managedConformanceExecutionContextForBundle(t, validCtx, "numeric-fan-out-reporter", runtime.sourceArtifactFact)); err != nil {
				t.Fatalf("run manager: %v", err)
			}
			publishNotifyAllChildrenRunCreatingEvent(t, validCtx, runtime, source, validRunID, "portfolio.opened", map[string]any{"portfolio_id": "portfolio-numeric-valid", "threshold": 75})
			assertNotifyAllChildrenMetadata(t, validCtx, selected, "portfolio", "portfolio_id", "portfolio-numeric-valid")
			transactions := storetest.CollectTransactions(t, selected, transactionOptions)
			t.Cleanup(func() {
				if t.Failed() {
					t.Logf("failed 500-row attempt transaction-owner snapshot (may include active work): %+v", transactions.Snapshot())
				}
			})
			issuanceStarted := time.Now()
			for batch := 0; batch < 20; batch++ {
				rows := make([]map[string]any, 0, 25)
				for row := 0; row < 25; row++ {
					ordinal := batch*25 + row
					rows = append(rows, map[string]any{"account_id": fmt.Sprintf("numeric-%03d", ordinal), "eng_roles": ordinal, "gem_score": float64(ordinal) + 0.25, "external_id": uuid.NewString()})
				}
				publishNotifyAllChildrenEventAsync(t, validCtx, runtime, source, validRunID, "portfolio.accounts.register.requested", map[string]any{"portfolio_id": "portfolio-numeric-valid", "account_ids": rows})
			}
			issuanceReached := waitNotifyAllChildrenFanOutCursor(t, runtime, validRunID, 500)
			var receipt storetest.TransactionSnapshot
			receiptDeadline := time.Now().Add(5 * time.Second)
			for {
				receipt = transactions.Snapshot()
				claims, chunks := receipt.ByOperation[storetest.TransactionFanOutClaim], receipt.ByOperation[storetest.TransactionFanOutChunk]
				if claims.WriteCommits >= 20 && chunks.WriteCommits >= 20 || time.Now().After(receiptDeadline) {
					break
				}
				time.Sleep(time.Millisecond)
			}
			t.Logf("500-row transaction-owner receipt through descendant quiescence (includes ingress, trigger, retained-session and downstream work; excludes implicit-autocommit SQL): total=%+v retained=%+v operations=%+v active=%d", receipt.Total, receipt.Retained, receipt.ByOperation, receipt.Active)
			claims, chunks := receipt.ByOperation[storetest.TransactionFanOutClaim], receipt.ByOperation[storetest.TransactionFanOutChunk]
			if claims.WriteCommits != 20 || chunks.WriteCommits != 20 || receipt.ByOperation[storetest.TransactionFanOutRelease].WriteCommits != 0 {
