	turnID := uuid.NewString()
	sessionID := uuid.NewString()
	surface, err := managedcapabilities.New(managedcapabilities.Plan{ActorIdentity: actorIdentity, RuntimeMode: "task", Provider: "test", Transport: "api", ProviderContract: "selected-http-proof", Authority: managedcapabilities.Authority{Kind: managedcapabilities.AuthorityProviderTurn, ID: turnID, ExecutionKind: managedcapabilities.ExecutionSelectedContractFork, ExecutionAuthorityID: proof.RuntimeExecutionID, RunID: proof.ForkRunID, SessionID: sessionID, TurnOrdinal: 1}, Tools: []managedcapabilities.PlannedTool{{Name: "selected_http", DefinitionHash: "selected-http-definition-v1", Capability: toolcapabilities.Capability{Name: "selected_http", Visible: true, Callable: true}, Bindings: []managedcapabilities.DeliveryBinding{{Kind: managedcapabilities.BindingAPIDefinition, ExactName: "selected_http", RequiredEvidenceKind: "api_definition_delivered"}}}}})
	if err != nil {
		t.Fatalf("build selected HTTP capability surface: %v", err)
	}
